import os,glob,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def f(g):
    g=[row[:] for row in g]
    H,W=len(g),len(g[0])
    from collections import Counter
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    seen=[[False]*W for _ in range(H)]
    out=[r[:] for r in g]
    # find connected components of non-bg cells
    import sys
    sys.setrecursionlimit(10000)
    def dfs(c,r):
        st=[(c,r)]; seen[c][r]=True; cells=[]
        while st:
            a,b=st.pop(); cells.append((a,b))
            for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                x,y=a+da,b+db
                if 0<=x<H and 0<=y<W and not seen[x][y] and g[x][y]!=bg:
                    seen[x][y]=True; st.append((x,y))
        return cells
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and not seen[i][j]:
                cells=dfs(i,j)
                rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
                rmin,rmax,cmin,cmax=min(rs),max(rs),min(cs),max(cs)
                for (r,c) in cells:
                    inside = rmin<r<rmax and cmin<c<cmax
                    if inside: out[r][c]=8
    return out
print(f(G['Demo pair 1 input'])==G['Demo pair 1 output'])
